--
-- Table structure for table `vendas`
--

DROP TABLE IF EXISTS `vendas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendas` (
  `id_venda` int NOT NULL AUTO_INCREMENT,
  `id_cliente` int NOT NULL,
  `id_operacao` int NOT NULL,
  `id_vendedor` int DEFAULT NULL,
  `numero_nf` int DEFAULT NULL,
  `serie_nf` int DEFAULT NULL,
  `chave_nfe` varchar(44) DEFAULT NULL,
  `data_venda` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status_venda` enum('Digitacao','Faturada','Cancelada') NOT NULL DEFAULT 'Digitacao',
  `valor_total_produtos` decimal(10,2) DEFAULT '0.00',
  `valor_desconto` decimal(10,2) DEFAULT '0.00',
  `valor_frete` decimal(10,2) DEFAULT '0.00',
  `valor_total_venda` decimal(10,2) DEFAULT '0.00',
  `gera_financeiro` tinyint(1) NOT NULL DEFAULT '0',
  `criado_por` int DEFAULT NULL,
  `gerou_financeiro` tinyint(1) DEFAULT '0',
  `vista` tinyint(1) DEFAULT '0',
  `id_vendedor1` int DEFAULT NULL,
  `id_vendedor2` int DEFAULT NULL,
  `numero_documento` varchar(50) DEFAULT NULL,
  `data_documento` datetime DEFAULT NULL,
  `valor_total` decimal(12,2) DEFAULT NULL,
  `id_financeiro_id` int DEFAULT NULL,
  `taxa_entrega` decimal(12,2) DEFAULT NULL,
  `venda_futura_origem` int DEFAULT NULL,
  `venda_futura_destino` int DEFAULT NULL,
  `protocolo_nfe` varchar(50) DEFAULT NULL,
  `xml_nfe` longtext,
  `status_nfe` varchar(20) DEFAULT 'PENDENTE',
  `numero_nfe` int DEFAULT NULL,
  `serie_nfe` int DEFAULT '1',
  `qrcode_nfe` text,
  `especie_volumes` varchar(60) DEFAULT NULL,
  `marca_volumes` varchar(60) DEFAULT NULL,
  `observacao_fisco` longtext,
  `peso_bruto` decimal(12,3) NOT NULL,
  `peso_liquido` decimal(12,3) NOT NULL,
  `placa_veiculo` varchar(8) DEFAULT NULL,
  `quantidade_volumes` int NOT NULL,
  `rntrc` varchar(20) DEFAULT NULL,
  `tipo_frete` int NOT NULL,
  `id_transportadora` int DEFAULT NULL,
  `uf_veiculo` varchar(2) DEFAULT NULL,
  `observacao_contribuinte` longtext,
  `mensagem_nfe` longtext,
  `chave_nfe_referenciada` varchar(50) DEFAULT NULL,
  `id_venda_faturamento` int DEFAULT NULL,
  `origem_venda` varchar(20) NOT NULL,
  `payment_id` varchar(100) DEFAULT NULL,
  `status_logistica` varchar(20) NOT NULL,
  `status_pagamento` varchar(20) NOT NULL,
  `data_prevista_entrega` date DEFAULT NULL,
  `endereco_entrega` longtext,
  `observacao_entrega` longtext,
  `responsavel_entrega` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`id_venda`),
  KEY `fk_vendas_cliente_idx` (`id_cliente`),
  KEY `fk_vendas_operacao_idx` (`id_operacao`),
  KEY `fk_vendas_vendedor_idx` (`id_vendedor`),
  KEY `fk_vendas_id_vendedor1` (`id_vendedor1`),
  KEY `fk_vendas_id_vendedor2` (`id_vendedor2`),
  KEY `vendas_id_financeiro_id_6002ac85_fk_financeiro_contas_id_conta` (`id_financeiro_id`),
  KEY `vendas_id_transportadora_318b8a46_fk_clientes_id_cliente` (`id_transportadora`),
  KEY `idx_venda_faturamento` (`id_venda_faturamento`),
  KEY `venda_data_doc_idx` (`data_documento`),
  KEY `venda_status_nfe_idx` (`status_nfe`),
  KEY `venda_data_status_idx` (`data_documento`,`status_nfe`),
  CONSTRAINT `fk_vendas_cliente` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id_cliente`),
  CONSTRAINT `fk_vendas_id_vendedor1` FOREIGN KEY (`id_vendedor1`) REFERENCES `vendedores` (`id_vendedor`),
  CONSTRAINT `fk_vendas_id_vendedor2` FOREIGN KEY (`id_vendedor2`) REFERENCES `vendedores` (`id_vendedor`),
  CONSTRAINT `fk_vendas_vendedor` FOREIGN KEY (`id_vendedor`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL,
  CONSTRAINT `vendas_id_financeiro_id_6002ac85_fk_financeiro_contas_id_conta` FOREIGN KEY (`id_financeiro_id`) REFERENCES `financeiro_contas` (`id_conta`),
  CONSTRAINT `vendas_id_transportadora_318b8a46_fk_clientes_id_cliente` FOREIGN KEY (`id_transportadora`) REFERENCES `clientes` (`id_cliente`)
) ENGINE=InnoDB AUTO_INCREMENT=463 DEFAULT CHARSET=utf8mb3;
